css:
.lab-workbench {
  --bg-paper: #f9f9f7;
  --ink: #2c2c2c;
  --muted: #666;
  --accent: #2b5797;
  --warm: #b85c38;
  --line: #e0e0e0;
  --glass: rgba(255, 255, 255, 0.7);

  font-family: system-ui, -apple-system, sans-serif;
  background-color: var(--bg-paper);
  color: var(--ink);
  padding: 2rem;
  line-height: 1.6;
  border-left: 4px solid var(--warm);
  max-width: 900px;
  margin: 0 auto;
}

.section-header h1 {
  font-size: 1.8rem;
  margin-bottom: 0.5rem;
  color: var(--ink);
}

.lead {
  font-size: 1.1rem;
  color: var(--muted);
  max-width: 700px;
}

.glass-card {
  background: var(--glass);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255, 255, 255, 0.5);
  border-radius: 8px;
  padding: 1.5rem;
  box-shadow: 0 4px 6px rgba(0,0,0,0.05);
  margin: 1.5rem 0;
}

.control-panel {
  display: flex;
  gap: 1.5rem;
  align-items: flex-end;
  flex-wrap: wrap;
}

.control-group {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.control-group label {
  font-size: 0.85rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--muted);
}

select, button {
  font-size: 1rem;
  padding: 0.5rem 1rem;
  border-radius: 4px;
  border: 1px solid var(--line);
  background: #fff;
  color: var(--ink);
  cursor: pointer;
}

button:hover {
  border-color: var(--accent);
}

.btn-secondary {
  background: #eee;
  border-color: #ddd;
}

.chart-container {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 1.5rem;
  margin-bottom: 1.5rem;
}

.chart-container h3 {
  margin-top: 0;
  font-size: 1.2rem;
}

.chart-note {
  font-size: 0.85rem;
  color: var(--muted);
  margin-bottom: 1.5rem;
}

.bar-chart {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.bar-row {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.bar-label {
  width: 140px;
  font-size: 0.9rem;
  font-weight: 500;
  text-align: right;
  flex-shrink: 0;
}

.bar-track {
  flex-grow: 1;
  height: 32px;
  background: #f0f0f0;
  border-radius: 4px;
  position: relative;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  background: var(--accent);
  width: 0%;
  transition: width 0.6s cubic-bezier(0.25, 0.8, 0.25, 1);
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding-right: 0.5rem;
  color: #fff;
  font-size: 0.85rem;
  font-weight: 600;
  white-space: nowrap;
}

.bar-fill.fever {
  background: var(--warm);
}

.legend {
  display: flex;
  gap: 1rem;
  margin-top: 1rem;
  font-size: 0.85rem;
  color: var(--muted);
  justify-content: center;
}

.dot {
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  margin-right: 4px;
}
.dot.qa { background: var(--accent); }
.dot.gen { background: #5a8fbf; }
.dot.fever { background: var(--warm); }

.analysis-card h3 {
  margin-top: 0;
}

.source-citation {
  margin-top: 1.5rem;
  padding-top: 1rem;
  border-top: 1px solid var(--line);
  display: flex;
  gap: 0.5rem;
}

.source-btn {
  font-size: 0.8rem;
  padding: 0.25rem 0.75rem;
  background: transparent;
  border: 1px solid var(--muted);
  color: var(--muted);
}

.source-btn:hover {
  background: var(--ink);
  color: #fff;
  border-color: var(--ink);
}

.limitation-box {
  font-size: 0.9rem;
  color: var(--muted);
  background: rgba(0,0,0,0.03);
  padding: 1rem;
  border-radius: 4px;
}

.limitation-box h4 {
  margin-top: 0;
  color: var(--ink);
}

.limitation-box ul {
  padding-left: 1.2rem;
  margin-bottom: 0;
}

@media (max-width: 600px) {
  .bar-row { flex-direction: column; align-items: flex-start; gap: 0.25rem; }
  .bar-label { text-align: left; width: auto; }
  .bar-track { width: 100%; }
  .control-panel { flex-direction: column; align-items: stretch; }
}

javascript:
(function() {
  'use strict';

  // Data Source: window.paperMindData.tables
  // Table ID: p8-Table_6
  const tableData = window.paperMindData.tables.find(t => t.id === 'p8-Table_6');

  if (!tableData) {
    console.error('Table 6 data not found in runtime context.');
    return;
  }

  // Mapping configuration based on Table 6 structure
  // Rows: 0:Token-BM25, 1:Seq-BM25, 2:Token-Frozen, 3:Seq-Frozen, 4:Token-Learned, 5:Seq-Learned
  // We group by Retriever Type for the UI logic
  const rows = tableData.rows;

  const retrieverGroups = {
    'bm25': [rows[0], rows[1]], // Token-BM25, Seq-BM25
    'frozen': [rows[2], rows[3]], // Token-Frozen, Seq-Frozen
    'learned': [rows[4], rows[5]] // Token-Learned, Seq-Learned
  };

  // Metrics mapping for visualization (Average of QA tasks vs FEVER)
  // QA Tasks: NQ, TQA, WQ, CT (Indices 1-4 in values object)
  // FEVER Tasks: FVR-3, FVR-2 (Indices 8-9 in values object)
  // We will display a composite view: Average QA Score vs FEVER Score

  const qaKeys = ['NQ', 'TQA', 'WQ', 'CT'];
  const feverKeys = ['FVR-3 Label Accuracy', 'FVR-2 Label Accuracy'];

  function calculateMetrics(row) {
    let qaSum = 0;
    let qaCount = 0;
    let feverSum = 0;
    let feverCount = 0;

    qaKeys.forEach(k => {
      const val = row.values[k];
      if (val !== null && val !== undefined) {
        qaSum += Number(val);
        qaCount++;
      }
    });

    feverKeys.forEach(k => {
      const val = row.values[k];
      if (val !== null && val !== undefined) {
        feverSum += Number(val);
        feverCount++;
      }
    });

    return {
      qa: qaCount > 0 ? (qaSum / qaCount).toFixed(1) : 'N/A',
      fever: feverCount > 0 ? (feverSum / feverCount).toFixed(1) : 'N/A'
    };
  }

  // DOM Elements
  const retrieverSelect = document.getElementById('retriever-select');
  const modelSelect = document.getElementById('model-variant');
  const barChart = document.getElementById('bar-chart');
  const analysisText = document.getElementById('analysis-text');
  const resetBtn = document.getElementById('reset-btn');

  function render() {
    const rType = retrieverSelect.value;
    const mType = modelSelect.value;

    // Find specific row
    const group = retrieverGroups[rType];
    const targetRow = group.find(r => r.label.toLowerCase().includes(mType));

    if (!targetRow) return;

    const metrics = calculateMetrics(targetRow);
    const baselineMetrics = calculateMetrics(retrieverGroups['learned'].find(r => r.label.toLowerCase().includes(mType)));

    // Render Bars
    barChart.innerHTML = '';

    // QA Bar
    const qaRow = document.createElement('div');
    qaRow.className = 'bar-row';
    qaRow.innerHTML = `
      <div class="bar-label">开放域问答 (Avg)</div>
      <div class="bar-track">
        <div class="bar-fill" style="width: ${metrics.qa}%">${metrics.qa}</div>
      </div>
    `;
    barChart.appendChild(qaRow);

    // FEVER Bar
    const feverRow = document.createElement('div');
    feverRow.className = 'bar-row';
    feverRow.innerHTML = `
      <div class="bar-label">事实核查 (FEVER)</div>
      <div class="bar-track">
        <div class="bar-fill fever" style="width: ${metrics.fever}%">${metrics.fever}</div>
      </div>
    `;
    barChart.appendChild(feverRow);

    // Render Analysis Text
    let analysis = '';
    if (rType === 'learned') {
      analysis = `<p><strong>最佳表现：</strong> 在大多数任务（如 NQ, TQA）上，可学习检索器（Learned Retriever）通过端到端训练，能够针对特定任务优化检索策略，从而获得最高分。</p>`;
      if (mType === 'token') analysis += `<p>RAG-Token 变体在生成任务中表现尤为突出，因为它可以为每个生成的 token 选择不同的检索文档。</p>`;
    } else if (rType === 'frozen') {
      const dropQa = (Number(baselineMetrics.qa) - Number(metrics.qa)).toFixed(1);
      analysis = `<p><strong>性能下降：</strong> 冻结检索器（Frozen）保留了 DPR 在 Natural Questions 上的预训练权重，但在其他任务上无法适应新分布。相比完整模型，QA 任务得分下降了约 ${dropQa} 分，证明联合训练的必要性。</p>`;
    } else if (rType === 'bm25') {
      if (Number(metrics.fever) > Number(baselineMetrics.fever)) {
        analysis = `<p><strong>FEVER 特异性：</strong> 在 FEVER 任务上，BM25 表现优于可学习检索器。这是因为 FEVER 声明高度依赖实体匹配，适合基于词重叠的检索。但在 QA 任务上，BM25 无法捕捉语义相似性，得分显著较低。</p>`;
      } else {
        analysis = `<p><strong>语义鸿沟：</strong> BM25 仅基于词重叠，无法捕捉查询与文档间的语义关联，导致在开放域问答任务上表现最差。</p>`;
      }
    }

    analysisText.innerHTML = analysis;
  }

  function reset() {
    retrieverSelect.value = 'learned';
    modelSelect.value = 'token';
    render();
  }

  // Event Listeners
  retrieverSelect.addEventListener('change', render);
  modelSelect.addEventListener('change', render);
  resetBtn.addEventListener('click', reset);

  // Initial Render
  render();
})();
